INSERT INTO nodes(id,symbol_id,domain,language,provider_id,entity_kind,language_kind,label,kind,qualified_name,package,namespace,source_file,source_location,begin_line,begin_column,end_line,end_column,source_ordinal,module,scope,metadata,producer_id,declaration_kind,type_kind,visibility,modifiers,declared_modifiers,implicit_modifiers,declaring_type,declaration_namespace,declaration_source_location,declaration_begin_line,declaration_begin_column,declaration_end_line,declaration_end_column,nesting_depth,direct_member,synthetic,binding_resolved,fact_hash,world) SELECT n.id,n.symbol_id,n.domain,n.language,n.provider_id,n.entity_kind,n.language_kind,n.label,n.kind,n.qualified_name,n.package,n.namespace,n.source_file,n.source_location,n.begin_line,n.begin_column,n.end_line,n.end_column,n.source_ordinal,n.module,n.scope,n.metadata,n.producer_id,d.declaration_kind,d.type_kind,d.visibility,d.modifiers,d.declared_modifiers,d.implicit_modifiers,d.declaring_type,d.namespace,d.source_location,d.begin_line,d.begin_column,d.end_line,d.end_column,d.nesting_depth,d.direct_member,d.synthetic,d.binding_resolved,n.fact_hash,n.world FROM staged.stage_nodes n LEFT JOIN staged.stage_declarations d ON d.provider_id=n.provider_id AND d.symbol_id=n.symbol_id AND d.module=n.module AND d.scope=n.scope AND d.source_file=n.source_file AND d.producer_id=n.producer_id ORDER BY n.seq;
INSERT INTO edges(source_id,target_id,external_target_fqn,external_target_symbol,external_target_language,external_target_provider_id,relation,semantic,mechanism,language,provider_id,call_kind,confidence,resolution,context,is_external,source_file,source_location,begin_line,begin_column,end_line,end_column,source_ordinal,syntax_target,receiver_static_type,metadata,producer_id,fact_hash,fact_ordinal) SELECT resolved_source,resolved_target,external_target_fqn,external_target_symbol,external_target_language,external_target_provider_id,relation,semantic,mechanism,language,provider_id,call_kind,confidence,resolution,context,is_external,source_file,source_location,begin_line,begin_column,end_line,end_column,source_ordinal,syntax_target,receiver_static_type,metadata,producer_id,fact_hash,fact_ordinal FROM staged.stage_edges s WHERE relation<>'CALLS' AND NOT EXISTS (SELECT 1 FROM edges e WHERE e.fact_hash=s.fact_hash AND e.fact_ordinal=s.fact_ordinal) ORDER BY seq;
INSERT INTO annotations(node_id,annotation_fqn,raw_name,attributes,target_kind,target_path,language,provider_id,mechanism,resolution_status,source_file,source_location,begin_line,begin_column,end_line,end_column,producer_id,fact_hash,fact_ordinal) SELECT resolved_node,annotation_fqn,raw_name,attributes,target_kind,target_path,language,provider_id,mechanism,resolution_status,source_file,source_location,begin_line,begin_column,end_line,end_column,producer_id,fact_hash,fact_ordinal FROM staged.stage_annotations s WHERE NOT EXISTS (SELECT 1 FROM annotations a WHERE a.fact_hash=s.fact_hash AND a.fact_ordinal=s.fact_ordinal) ORDER BY seq;
INSERT INTO semantic_annotations(node_id,category,business_label,business_description,domain_context,source,confidence,source_file,producer_id) SELECT resolved_node,category,business_label,business_description,domain_context,source,confidence,source_file,producer_id FROM staged.stage_semantic_annotations s WHERE resolved_node IS NOT NULL AND NOT EXISTS(SELECT 1 FROM semantic_annotations a WHERE a.node_id=s.resolved_node AND a.category=s.category AND a.producer_id=s.producer_id AND coalesce(a.source,'')=coalesce(s.source,'')) ORDER BY seq;
